    @staticmethod
    def _terminal_reset_prob_from_count(count_target, n_samples):
        denom = float(max(1, int(n_samples)))
        if torch.is_tensor(count_target):
            prob = count_target.to(dtype=torch.float32) / denom
            return torch.clamp(prob, min=0.0, max=1.0)
        return float(max(0.0, min(1.0, float(count_target) / denom)))

    @staticmethod
    def _terminal_count_summary(realized_count, target_count, *, enabled=None, device=None, dtype=torch.float32):
        realized_t = realized_count
        if not torch.is_tensor(realized_t):
            realized_t = torch.as_tensor(realized_t, device=device, dtype=dtype)
        else:
            realized_t = realized_t.to(device=device, dtype=dtype)
        target_t = target_count
        if not torch.is_tensor(target_t):
            target_t = torch.as_tensor(target_t, device=realized_t.device, dtype=dtype)
        else:
            target_t = target_t.to(device=realized_t.device, dtype=dtype)
        realized_flat = realized_t.reshape(-1)
        target_flat = target_t.reshape(-1)
        if enabled is not None:
            enabled_t = enabled
            if not torch.is_tensor(enabled_t):
                enabled_t = torch.as_tensor(enabled_t, device=realized_t.device, dtype=torch.bool)
            else:
                enabled_t = enabled_t.to(device=realized_t.device, dtype=torch.bool)
            enabled_flat = enabled_t.reshape(-1)
            if enabled_flat.numel() != realized_flat.numel():
                raise ValueError("enabled must match realized_count shape in _terminal_count_summary")
            if not bool(enabled_flat.any().item()):
                return None
            realized_flat = realized_flat[enabled_flat]
            target_flat = target_flat[enabled_flat]
        return {
            "terminal_count_mean": realized_flat.mean().detach(),
            "terminal_count_min": realized_flat.min().detach(),
            "terminal_count_max": realized_flat.max().detach(),
            "terminal_count_target_mean": target_flat.mean().detach(),
            "terminal_count_target_min": target_flat.min().detach(),
            "terminal_count_target_max": target_flat.max().detach(),
        }

    @staticmethod
    def _merge_terminal_count_summary(acc, summary, *, batch_weight, device=None, dtype=torch.float32):
        if not isinstance(summary, dict):
            return acc
        if acc is None:
            acc = {
                "terminal_count_mean": torch.zeros((), device=device, dtype=dtype),
                "terminal_count_min": None,
                "terminal_count_max": None,
                "terminal_count_target_mean": torch.zeros((), device=device, dtype=dtype),
                "terminal_count_target_min": None,
                "terminal_count_target_max": None,
            }

        def _to_tensor(key, default=0.0):
            value = summary.get(key, default)
            if not torch.is_tensor(value):
                value = torch.as_tensor(value, device=device, dtype=dtype)
            else:
                value = value.to(device=device, dtype=dtype)
            return value.detach()

        realized_mean = _to_tensor("terminal_count_mean")
        realized_min = _to_tensor("terminal_count_min")
        realized_max = _to_tensor("terminal_count_max")
        target_mean = _to_tensor("terminal_count_target_mean")
        target_min = _to_tensor("terminal_count_target_min")
        target_max = _to_tensor("terminal_count_target_max")

        acc["terminal_count_mean"] = acc["terminal_count_mean"] + (realized_mean * float(batch_weight))
        acc["terminal_count_target_mean"] = acc["terminal_count_target_mean"] + (target_mean * float(batch_weight))
        acc["terminal_count_min"] = realized_min if acc["terminal_count_min"] is None else torch.minimum(acc["terminal_count_min"], realized_min)
        acc["terminal_count_max"] = realized_max if acc["terminal_count_max"] is None else torch.maximum(acc["terminal_count_max"], realized_max)
        acc["terminal_count_target_min"] = target_min if acc["terminal_count_target_min"] is None else torch.minimum(acc["terminal_count_target_min"], target_min)
        acc["terminal_count_target_max"] = target_max if acc["terminal_count_target_max"] is None else torch.maximum(acc["terminal_count_target_max"], target_max)
        return acc

    @staticmethod
    def _finalize_terminal_count_summary(summary, *, device=None, dtype=torch.float32):
        if summary is None:
            return None
        out = {}
        for key, value in summary.items():
            if value is None:
                continue
            if not torch.is_tensor(value):
                out[key] = torch.as_tensor(value, device=device, dtype=dtype)
            else:
                out[key] = value.to(device=device, dtype=dtype)
        return out

    @staticmethod
    def _terminal_tail_event_from_signal(
        terminal_signal,
        *,
        enabled,
        reset_prob,
        terminal_draw=None,
        signal_history=None,
        history_length=0,
    ):
        if terminal_signal is None:
            raise ValueError("terminal_signal must be provided for tail-triggered reset")
        signal_t = terminal_signal
        if not torch.is_tensor(signal_t):
            signal_t = torch.as_tensor(signal_t, dtype=torch.float32)
        if signal_t.ndim > 0 and signal_t.shape[-1] == 1:
            signal_t = signal_t.squeeze(-1)
        enabled_t = enabled
        if not torch.is_tensor(enabled_t):
            enabled_t = torch.as_tensor(enabled_t, device=signal_t.device, dtype=torch.bool)
        else:
            enabled_t = enabled_t.to(device=signal_t.device, dtype=torch.bool)
        if enabled_t.ndim < signal_t.ndim:
            enabled_t = enabled_t.reshape(signal_t.shape)
        if not bool(enabled_t.any().item()):
            return torch.zeros_like(signal_t, dtype=torch.bool)
        prob_t = torch.as_tensor(reset_prob, device=signal_t.device, dtype=signal_t.dtype)
        while prob_t.ndim < signal_t.ndim:
            prob_t = prob_t.unsqueeze(-1)
        prob_t = torch.clamp(prob_t, min=0.0, max=1.0)
        if not bool((prob_t[enabled_t] > 0).any().item()):
            return torch.zeros_like(signal_t, dtype=torch.bool)
        if bool((prob_t[enabled_t] >= 1).all().item()):
            return enabled_t.clone()
        history_len = int(max(0, int(history_length)))
        enabled_idx = torch.nonzero(enabled_t.reshape(-1), as_tuple=False).reshape(-1)
        if enabled_idx.numel() <= 0:
            return torch.zeros_like(signal_t, dtype=torch.bool)
        draw_t = terminal_draw
        if draw_t is None:
            draw_t = torch.zeros_like(signal_t.reshape(-1))
        elif not torch.is_tensor(draw_t):
            draw_t = torch.as_tensor(draw_t, device=signal_t.device, dtype=signal_t.dtype)
        else:
            draw_t = draw_t.to(device=signal_t.device, dtype=signal_t.dtype)
        if draw_t.ndim > 0 and draw_t.shape[-1] == 1:
            draw_t = draw_t.squeeze(-1)
        draw_enabled = draw_t.reshape(-1).index_select(0, enabled_idx)
        prob_enabled = prob_t.reshape(-1).index_select(0, enabled_idx)
        signal_enabled = signal_t.reshape(-1).index_select(0, enabled_idx)
        terminal_enabled = torch.zeros_like(signal_enabled, dtype=torch.bool)
        history_t = signal_history
        if (history_t is not None) and (history_len > 0):
            if not torch.is_tensor(history_t):
                history_t = torch.as_tensor(history_t, device=signal_t.device, dtype=signal_t.dtype)
            else:
                history_t = history_t.to(device=signal_t.device, dtype=signal_t.dtype)
            if history_t.ndim == 1:
                history_t = history_t.unsqueeze(-1)
            if history_t.ndim == 3 and history_t.shape[-1] == 1:
                history_t = history_t.squeeze(-1)
            if history_t.ndim != 2:
                raise ValueError("signal_history must be rank-2 [time, batch]")
            if history_t.shape[1] != signal_t.reshape(-1).shape[0]:
                raise ValueError("signal_history batch dimension must match terminal_signal")
            history_t = history_t[:history_len]
            if history_t.shape[0] > 0:
                hist_enabled = history_t.index_select(1, enabled_idx)
                n_hist = int(hist_enabled.shape[0])
                sorted_history, _ = torch.sort(hist_enabled, dim=0)
                tail_prob = torch.clamp(prob_enabled * 0.5, min=0.0, max=0.5)
                tail_count_real = tail_prob * float(n_hist + 1)
                tail_count_floor = torch.floor(tail_count_real).to(dtype=torch.long)
                tail_count_frac = torch.clamp(
                    tail_count_real - tail_count_floor.to(dtype=signal_t.dtype),
                    min=0.0,
                    max=1.0,
                )
                resolvable = tail_count_floor > 0
                if bool(resolvable.any().item()):
                    history_idx = torch.nonzero(resolvable, as_tuple=False).reshape(-1)
                    signal_hist = signal_enabled.index_select(0, history_idx)
                    draw_hist = draw_enabled.index_select(0, history_idx)
                    tail_floor_hist = tail_count_floor.index_select(0, history_idx)
                    tail_frac_hist = tail_count_frac.index_select(0, history_idx)
                    sorted_hist = sorted_history.index_select(1, history_idx)
                    cols = torch.arange(history_idx.numel(), device=signal_t.device, dtype=torch.long)

                    lower_cut = sorted_hist[tail_floor_hist - 1, cols]
                    lower_strict = signal_hist < lower_cut
                    lower_boundary = torch.zeros_like(lower_strict)
                    has_lower_boundary = tail_floor_hist < n_hist
                    if bool(has_lower_boundary.any().item()):
                        hb_idx = torch.nonzero(has_lower_boundary, as_tuple=False).reshape(-1)
                        next_lower_cut = sorted_hist[
                            tail_floor_hist.index_select(0, hb_idx),
                            cols.index_select(0, hb_idx),
                        ]
                        lower_boundary.index_copy_(
                            0,
                            hb_idx,
                            (
                                (signal_hist.index_select(0, hb_idx) >= lower_cut.index_select(0, hb_idx))
                                & (signal_hist.index_select(0, hb_idx) < next_lower_cut)
                                & (draw_hist.index_select(0, hb_idx) < tail_frac_hist.index_select(0, hb_idx))
                            ),
                        )

                    upper_cut = sorted_hist[n_hist - tail_floor_hist, cols]
                    upper_strict = signal_hist > upper_cut
                    upper_boundary = torch.zeros_like(upper_strict)
                    has_upper_boundary = tail_floor_hist < n_hist
                    if bool(has_upper_boundary.any().item()):
                        hb_idx = torch.nonzero(has_upper_boundary, as_tuple=False).reshape(-1)
                        prev_upper_cut = sorted_hist[
                            (n_hist - tail_floor_hist.index_select(0, hb_idx) - 1),
                            cols.index_select(0, hb_idx),
                        ]
                        upper_boundary.index_copy_(
                            0,
                            hb_idx,
                            (
                                (signal_hist.index_select(0, hb_idx) <= upper_cut.index_select(0, hb_idx))
                                & (signal_hist.index_select(0, hb_idx) > prev_upper_cut)
                                & (draw_hist.index_select(0, hb_idx) < tail_frac_hist.index_select(0, hb_idx))
                            ),
                        )
                    history_result = lower_strict | lower_boundary | upper_strict | upper_boundary
                    terminal_enabled.index_copy_(0, history_idx, history_result)
        terminal_out = torch.zeros_like(signal_t.reshape(-1), dtype=torch.bool)
        terminal_out.index_copy_(0, enabled_idx, terminal_enabled)
        return terminal_out.reshape(signal_t.shape) & enabled_t

    @staticmethod
    def _terminal_bonus_from_signal(
        terminal_signal,
        *,
        bonus_scale,
        tanh_c=10.0,
    ):
        raw_bonus = terminal_signal
        if not torch.is_tensor(raw_bonus):
            raw_bonus = torch.as_tensor(raw_bonus, dtype=torch.float32)
        if raw_bonus.ndim > 0 and raw_bonus.shape[-1] == 1:
            raw_bonus = raw_bonus.squeeze(-1)
        c_t = torch.as_tensor(tanh_c, device=raw_bonus.device, dtype=raw_bonus.dtype)
        scale_t = torch.as_tensor(bonus_scale, device=raw_bonus.device, dtype=raw_bonus.dtype)
        while c_t.ndim < raw_bonus.ndim:
            c_t = c_t.unsqueeze(0)
        while scale_t.ndim < raw_bonus.ndim:
            scale_t = scale_t.unsqueeze(0)
        return scale_t * torch.tanh(raw_bonus / c_t)

    @staticmethod
    def _terminal_bonus_base_from_signal(terminal_signal, *, tanh_c=10.0):
        raw_bonus = terminal_signal
        if not torch.is_tensor(raw_bonus):
            raw_bonus = torch.as_tensor(raw_bonus, dtype=torch.float32)
        if raw_bonus.ndim > 0 and raw_bonus.shape[-1] == 1:
            raw_bonus = raw_bonus.squeeze(-1)
        c_t = torch.as_tensor(tanh_c, device=raw_bonus.device, dtype=raw_bonus.dtype)
        while c_t.ndim < raw_bonus.ndim:
            c_t = c_t.unsqueeze(0)
        return torch.tanh(raw_bonus / c_t)

    @staticmethod
    def _terminal_bonus_scale_from_draw(draw, *, scale_min, scale_max):
        draw_t = draw
        if not torch.is_tensor(draw_t):
            draw_t = torch.as_tensor(draw_t, dtype=torch.float32)
        lo_t = torch.as_tensor(scale_min, device=draw_t.device, dtype=draw_t.dtype)
        hi_t = torch.as_tensor(scale_max, device=draw_t.device, dtype=draw_t.dtype)
        while lo_t.ndim < draw_t.ndim:
            lo_t = lo_t.unsqueeze(0)
        while hi_t.ndim < draw_t.ndim:
            hi_t = hi_t.unsqueeze(0)
        return lo_t + (hi_t - lo_t) * draw_t

    def _apply_terminal_reset_step(
        self,
        *,
        state_next,
        reward_next,
        terminal_draw,
        reset_prob,
        bonus_scale_draw,
        bonus_scale_min,
        bonus_scale_max,
        bonus_tanh_c,
        reset_state,
        enabled,
        terminal_signal,
        terminal_bonus_base=None,
        terminal_signal_history=None,
        history_index=None,
        return_aux=False,
    ):
        enabled_t = enabled
        if not torch.is_tensor(enabled_t):
            enabled_t = torch.as_tensor(enabled_t, device=state_next.device, dtype=torch.bool)
        else:
            enabled_t = enabled_t.to(device=state_next.device, dtype=torch.bool)
        if not bool(enabled_t.any().item()):
            terminal_zero = torch.zeros_like(reward_next, dtype=reward_next.dtype)
            if not return_aux:
                return state_next, reward_next, terminal_zero
            aux = {
                "terminal_bonus_applied": torch.zeros_like(reward_next, dtype=reward_next.dtype),
                "terminal_bonus_event": torch.zeros_like(reward_next, dtype=reward_next.dtype),
                "terminal_event_mask": torch.zeros_like(reward_next, dtype=torch.bool),
            }
            return state_next, reward_next, terminal_zero, aux
        if terminal_signal is None:
            raise ValueError("terminal_signal must be provided when terminal reset is enabled")
        prob_t = torch.as_tensor(reset_prob, device=state_next.device, dtype=state_next.dtype)
        while prob_t.ndim < reward_next.ndim:
            prob_t = prob_t.unsqueeze(0)
        bonus_scale_t = self._terminal_bonus_scale_from_draw(
            bonus_scale_draw.to(device=state_next.device, dtype=state_next.dtype),
            scale_min=bonus_scale_min,
            scale_max=bonus_scale_max,
        )
        terminal_signal_t = terminal_signal.to(device=state_next.device, dtype=state_next.dtype)
        if terminal_bonus_base is None:
            terminal_bonus_t = self._terminal_bonus_from_signal(
                terminal_signal_t,
                bonus_scale=bonus_scale_t,
                tanh_c=bonus_tanh_c,
            )
        else:
            terminal_bonus_t = bonus_scale_t * terminal_bonus_base.to(
                device=state_next.device,
                dtype=state_next.dtype,
            )
        terminal_signal_event = terminal_signal_t.detach()
        terminal_next = self._terminal_tail_event_from_signal(
            terminal_signal_event,
            enabled=enabled_t,
            reset_prob=prob_t,
            terminal_draw=terminal_draw,
            signal_history=terminal_signal_history,
            history_length=history_index,
        )
        if terminal_signal_history is not None and history_index is not None:
            hist_t = terminal_signal_history
            if not torch.is_tensor(hist_t):
                raise ValueError("terminal_signal_history must be a tensor")
            signal_store = terminal_signal_event.reshape(-1).to(device=hist_t.device, dtype=hist_t.dtype)
            hist_t[history_index].copy_(signal_store)
        terminal_bonus_t = terminal_bonus_t.to(device=state_next.device, dtype=reward_next.dtype)
        terminal_bonus_applied = terminal_bonus_t * terminal_next.to(dtype=reward_next.dtype)
        reward_next = reward_next + terminal_bonus_applied
        terminal_mask = terminal_next
        if terminal_mask.ndim < state_next.ndim:
            terminal_mask = terminal_mask.unsqueeze(-1)
        state_next = torch.where(
            terminal_mask,
            reset_state.to(device=state_next.device, dtype=state_next.dtype),
            state_next,
        )
        terminal_next_out = terminal_next.to(dtype=reward_next.dtype)
        if not return_aux:
            return state_next, reward_next, terminal_next_out
        aux = {
            "terminal_bonus_applied": terminal_bonus_applied.detach(),
            "terminal_bonus_event": terminal_bonus_t.detach(),
            "terminal_event_mask": terminal_next.to(dtype=torch.bool).detach(),
        }
        return state_next, reward_next, terminal_next_out, aux

    @staticmethod
    def _clip_tensor_grad_by_global_norm(tensor, *, max_norm=0.0):
        if (not torch.is_tensor(tensor)) or (not bool(tensor.requires_grad)):
            return tensor
        if torch.is_tensor(max_norm):
            max_norm_t = max_norm.to(device=tensor.device, dtype=tensor.dtype)
            if max_norm_t.numel() != 1:
                raise ValueError("max_norm tensor must be scalar")
            max_norm_value = float(max_norm_t.detach().item())
        else:
            max_norm_value = float(max_norm)
            max_norm_t = torch.as_tensor(max_norm_value, device=tensor.device, dtype=tensor.dtype)
        if (not math.isfinite(max_norm_value)) or max_norm_value <= 0.0:
            return tensor

        def _hook(grad):
            if grad is None:
                return grad
            grad = torch.nan_to_num(
                grad,
                nan=0.0,
                posinf=max_norm_value,
                neginf=-max_norm_value,
            )
            if grad.ndim <= 1:
                grad_flat = grad.reshape(1, -1)
            else:
                grad_flat = grad.reshape(grad.shape[0], -1)
            grad_norm = grad_flat.norm(dim=-1, keepdim=True)
            scale = torch.clamp(max_norm_t / grad_norm.clamp_min(max_norm_t), max=1.0)
            while scale.ndim < grad.ndim:
                scale = scale.unsqueeze(-1)
            return grad * scale

        tensor.register_hook(_hook)
        return tensor

    @staticmethod
    def _clip_tensor_grad_by_value(tensor, *, max_abs=0.0):
        if (not torch.is_tensor(tensor)) or (not bool(tensor.requires_grad)):
            return tensor
        if torch.is_tensor(max_abs):
            max_abs_t = max_abs.to(device=tensor.device, dtype=tensor.dtype)
            if max_abs_t.numel() != 1:
                raise ValueError("max_abs tensor must be scalar")
            max_abs_value = float(max_abs_t.detach().item())
        else:
            max_abs_value = float(max_abs)
            max_abs_t = torch.as_tensor(max_abs_value, device=tensor.device, dtype=tensor.dtype)
        if (not math.isfinite(max_abs_value)) or max_abs_value <= 0.0:
            return tensor

        def _hook(grad):
            if grad is None:
                return grad
            grad = torch.nan_to_num(
                grad,
                nan=0.0,
                posinf=max_abs_value,
                neginf=-max_abs_value,
            )
            return torch.clamp(grad, min=-max_abs_t, max=max_abs_t)

        tensor.register_hook(_hook)
        return tensor

    @staticmethod
    def _transform_reinforce_action(action_raw, *, mode="rms", rms_eps=1e-6, mask=None):
        mode = str(mode).strip().lower()
        if mode == "tanh":
            action_next = torch.tanh(action_raw)
        elif mode == "rms":
            if mask is None:
                mask_t = torch.ones_like(action_raw, dtype=action_raw.dtype)
            else:
                mask_t = mask.to(device=action_raw.device, dtype=action_raw.dtype)
                while mask_t.ndim < action_raw.ndim:
                    mask_t = mask_t.unsqueeze(0)
                mask_t = mask_t.expand_as(action_raw)
            denom = mask_t.sum(dim=-1).clamp_min(1.0)
            eps_t = torch.as_tensor(rms_eps, device=action_raw.device, dtype=action_raw.dtype)
            while eps_t.ndim < denom.ndim:
                eps_t = eps_t.unsqueeze(0)
            rms = torch.sqrt(((action_raw * mask_t) ** 2).sum(dim=-1) / denom + eps_t)
            rms = rms.detach()
            while rms.ndim < action_raw.ndim:
                rms = rms.unsqueeze(-1)
            action_next = (action_raw / rms) * mask_t
        elif mode == "none":
            action_next = action_raw
            if mask is not None:
                mask_t = mask.to(device=action_raw.device, dtype=action_raw.dtype)
                while mask_t.ndim < action_raw.ndim:
                    mask_t = mask_t.unsqueeze(0)
                action_next = action_next * mask_t
        else:
            raise ValueError(f"Unknown reinforce action transform: {mode}")
        return action_next

    @staticmethod
    def _unpack_policy_step_output(policy_out):
        cache = None
        main_out = policy_out
        if isinstance(policy_out, tuple):
            if len(policy_out) != 2:
                raise ValueError(
                    "policy_step_fn must return either action tensor / actor dict, "
                    f"or a (output, cache) tuple; got tuple len={len(policy_out)}"
                )
            main_out, cache = policy_out
        actor_outputs = (
            main_out
            if isinstance(main_out, dict) and torch.is_tensor(main_out.get("action_mean", None))
            else None
        )
        action_mean = actor_outputs["action_mean"] if actor_outputs is not None else main_out
        return actor_outputs, action_mean, cache

    @staticmethod
    def _reduce_action_std_for_storage(action_std, *, action_mask=None, eps=1e-6):
        if action_std is None:
            return None
        if not torch.is_tensor(action_std):
            action_std = torch.as_tensor(action_std, dtype=torch.float32)
        action_std = action_std.to(dtype=torch.float32)
        if action_std.ndim <= 1:
            return action_std.detach()
        if action_mask is None:
            return action_std.mean(dim=-1).detach()
        mask_t = action_mask.to(device=action_std.device, dtype=action_std.dtype)
        while mask_t.ndim < action_std.ndim:
            mask_t = mask_t.unsqueeze(0)
        denom = mask_t.sum(dim=-1).clamp_min(float(eps))
        return ((action_std * mask_t).sum(dim=-1) / denom).detach()

    def _resolve_policy_action_sample(
        self,
        *,
        policy_step_fn,
        actor_outputs,
        action_mean,
        sample_action,
        action_eps_t,
        action_mask=None,
        action_transform_mode="rms",
        action_rms_eps=1e-6,
        collect_log_probs=False,
        collect_log_prob_score=False,
        legacy_action_std=None,
    ):
        actor_sample_fn = getattr(policy_step_fn, "_policy_actor_sample_fn", None)
        actor_log_prob_fn = getattr(policy_step_fn, "_policy_actor_log_prob_fn", None)
        actor_score_fn = getattr(policy_step_fn, "_policy_actor_score_fn", None)

        action_std_for_storage = None
        if actor_outputs is not None:
            if sample_action:
                if callable(actor_sample_fn):
                    action_raw = actor_sample_fn(actor_outputs, noise=action_eps_t)
                else:
                    actor_std = actor_outputs.get("action_std", None)
                    if actor_std is None:
                        raise RuntimeError(
                            "policy_step_fn returned actor outputs, but neither actor sample function nor action_std is available"
                        )
                    action_raw = actor_outputs["action_mean"] + (action_eps_t * actor_std)
            else:
                action_raw = actor_outputs["action_mean"]
            action_next = self._transform_reinforce_action(
                action_raw,
                mode=action_transform_mode,
                rms_eps=action_rms_eps,
                mask=action_mask,
            )
            action_std_for_storage = self._reduce_action_std_for_storage(
                actor_outputs.get("action_std", None),
                action_mask=action_mask,
            )
            reinforce_log_prob_t = None
            reinforce_log_prob_score_t = None
            if collect_log_probs:
                if callable(actor_log_prob_fn):
                    reinforce_log_prob_t = actor_log_prob_fn(
                        actor_outputs,
                        action_next.detach(),
                        action_mask=action_mask,
                    )
                else:
                    actor_std = actor_outputs.get("action_std", None)
                    if actor_std is None:
                        raise RuntimeError(
                            "actor outputs omitted action_std and no actor log-prob function is attached"
                        )
                    reinforce_log_prob_t = self._gaussian_log_prob(
                        action_next.detach(),
                        actor_outputs["action_mean"],
                        actor_std,
                        mask=action_mask,
                    )
                if collect_log_prob_score:
                    if callable(actor_score_fn):
                        reinforce_log_prob_score_t = actor_score_fn(
                            actor_outputs,
                            action_next.detach(),
                            action_mask=action_mask,
                        ).detach().to(dtype=torch.float32)
                    else:
                        actor_std = actor_outputs.get("action_std", None)
                        if actor_std is None:
                            raise RuntimeError(
                                "actor outputs omitted action_std and no actor score function is attached"
                            )
                        reinforce_log_prob_score_t = self._reinforce_log_prob_score_wrt_action_mean(
                            action_next.detach(),
                            actor_outputs["action_mean"].detach(),
                            actor_std,
                            mask=action_mask,
                        ).detach().to(dtype=torch.float32)
                    reinforce_log_prob_t = reinforce_log_prob_t.detach()
            return {
                "action_next": action_next,
                "action_std_for_storage": action_std_for_storage,
                "log_prob": reinforce_log_prob_t,
                "log_prob_score": reinforce_log_prob_score_t,
            }

        if sample_action:
            if legacy_action_std is None:
                raise RuntimeError("legacy policy sampling requires legacy_action_std")
            legacy_action_std_t = torch.as_tensor(
                legacy_action_std,
                device=action_mean.device,
                dtype=action_mean.dtype,
            )
            if torch.any(legacy_action_std_t <= 0):
                raise ValueError("stochastic policy objective requires positive legacy action std")
            while legacy_action_std_t.ndim < action_mean.ndim:
                legacy_action_std_t = legacy_action_std_t.unsqueeze(-1)
            action_pre_tanh = action_mean + (action_eps_t * legacy_action_std_t)
            action_next = self._transform_reinforce_action(
                action_pre_tanh,
                mode=action_transform_mode,
                rms_eps=action_rms_eps,
                mask=action_mask,
            )
            reinforce_log_prob_t = None
            reinforce_log_prob_score_t = None
            if collect_log_probs:
                reinforce_log_prob_t = self._gaussian_log_prob(
                    action_next.detach(),
                    action_mean,
                    legacy_action_std_t,
                    mask=action_mask,
                )
                if collect_log_prob_score:
                    reinforce_log_prob_score_t = self._reinforce_log_prob_score_wrt_action_mean(
                        action_next.detach(),
                        action_mean.detach(),
                        legacy_action_std_t,
                        mask=action_mask,
                    ).detach().to(dtype=torch.float32)
                    reinforce_log_prob_t = reinforce_log_prob_t.detach()
            return {
                "action_next": action_next,
                "action_std_for_storage": self._reduce_action_std_for_storage(
                    legacy_action_std_t,
                    action_mask=action_mask,
                ),
                "log_prob": reinforce_log_prob_t,
                "log_prob_score": reinforce_log_prob_score_t,
            }

        action_next = self._transform_reinforce_action(
            action_mean,
            mode=action_transform_mode,
            rms_eps=action_rms_eps,
            mask=action_mask,
        )
        return {
            "action_next": action_next,
            "action_std_for_storage": (
                torch.as_tensor(legacy_action_std, device=action_mean.device, dtype=torch.float32).detach()
                if legacy_action_std is not None
                else None
            ),
            "log_prob": None,
            "log_prob_score": None,
        }

    @staticmethod
    def _exact_scm_aux_reward_components(
        action,
        *,
        action_mask=None,
        ctrl_weight=0.0,
        ctrl_enabled=False,
        survival_weight=0.0,
        survival_enabled=False,
    ):
        if not torch.is_tensor(action):
            action_t = torch.as_tensor(action, dtype=torch.float32)
        else:
            action_t = action
        if action_mask is None:
            mask_t = torch.ones_like(action_t, dtype=action_t.dtype)
        else:
            mask_t = action_mask.to(device=action_t.device, dtype=action_t.dtype)
            while mask_t.ndim < action_t.ndim:
                mask_t = mask_t.unsqueeze(0)
            mask_t = mask_t.expand_as(action_t)
        ctrl_denom = mask_t.sum(dim=-1).clamp_min(1.0)
        ctrl_mean_sq = ((action_t * mask_t) ** 2).sum(dim=-1) / ctrl_denom
        ctrl_weight_t = torch.as_tensor(ctrl_weight, device=action_t.device, dtype=action_t.dtype)
        survival_weight_t = torch.as_tensor(survival_weight, device=action_t.device, dtype=action_t.dtype)
        ctrl_enabled_t = torch.as_tensor(ctrl_enabled, device=action_t.device, dtype=torch.bool)
        survival_enabled_t = torch.as_tensor(survival_enabled, device=action_t.device, dtype=torch.bool)
        while ctrl_weight_t.ndim < ctrl_mean_sq.ndim:
            ctrl_weight_t = ctrl_weight_t.unsqueeze(0)
        while survival_weight_t.ndim < ctrl_mean_sq.ndim:
            survival_weight_t = survival_weight_t.unsqueeze(0)
        while ctrl_enabled_t.ndim < ctrl_mean_sq.ndim:
            ctrl_enabled_t = ctrl_enabled_t.unsqueeze(0)
        while survival_enabled_t.ndim < ctrl_mean_sq.ndim:
            survival_enabled_t = survival_enabled_t.unsqueeze(0)
        ctrl_reward = torch.where(
            ctrl_enabled_t,
            -ctrl_weight_t * ctrl_mean_sq,
            torch.zeros_like(ctrl_mean_sq),
        )
        survival_reward = torch.where(
            survival_enabled_t,
            survival_weight_t.expand_as(ctrl_mean_sq),
            torch.zeros_like(ctrl_mean_sq),
        )
        return ctrl_reward, survival_reward

    @staticmethod
    def _exact_scm_aux_reward_terms(
        action,
        *,
        action_mask=None,
        ctrl_weight=0.0,
        ctrl_enabled=False,
        survival_weight=0.0,
        survival_enabled=False,
    ):
        ctrl_reward, survival_reward = EnvironmentPrior._exact_scm_aux_reward_components(
            action,
            action_mask=action_mask,
            ctrl_weight=ctrl_weight,
            ctrl_enabled=ctrl_enabled,
            survival_weight=survival_weight,
            survival_enabled=survival_enabled,
        )
        return ctrl_reward + survival_reward

    def _transform_exact_scm_base_reward(
        self,
        reward_raw,
        *,
        reward_clip=10.0,
        mode="none",
        rms_eps=1e-6,
        tanh_c=1.0,
        tanh_bound=2.0,
    ):
        reward_clip_t = torch.as_tensor(reward_clip, device=reward_raw.device, dtype=reward_raw.dtype)
        while reward_clip_t.ndim < reward_raw.ndim:
            reward_clip_t = reward_clip_t.unsqueeze(0)
        reward_base = torch.maximum(torch.minimum(reward_raw, reward_clip_t), -reward_clip_t)
        reward_base = self._transform_rollout_reward(
            reward_base,
            mode=mode,
            rms_eps=rms_eps,
            tanh_c=tanh_c,
            tanh_bound=tanh_bound,
        )
        return reward_base

    @staticmethod
    def _accumulate_reward_component_profile_stats(stats_accum, name, values):
        if stats_accum is None or values is None:
            return
        det = values.detach().to(dtype=torch.float64)
        entry = stats_accum.setdefault(
            str(name),
            {
                "sum": None,
                "sumsq": None,
                "count": 0,
            },
        )
        value_sum = det.sum()
        value_sumsq = (det * det).sum()
        entry["sum"] = value_sum if entry["sum"] is None else (entry["sum"] + value_sum)
        entry["sumsq"] = value_sumsq if entry["sumsq"] is None else (entry["sumsq"] + value_sumsq)
        entry["count"] += int(det.numel())

    @staticmethod
    def _finalize_reward_component_profile_stats(stats_accum, *, device):
        out = {}
        device_obj = device if isinstance(device, torch.device) else torch.device(str(device))
        zero = torch.zeros((), device=device_obj, dtype=torch.float32)
        for name, entry in (stats_accum or {}).items():
            count = int(entry.get("count", 0) or 0)
            if count <= 0 or entry.get("sum", None) is None or entry.get("sumsq", None) is None:
                mean_t = zero
                std_t = zero
            else:
                sum_t = entry["sum"]
                sumsq_t = entry["sumsq"]
                mean64 = sum_t / float(count)
                var64 = (sumsq_t / float(count)) - (mean64 * mean64)
                std64 = torch.sqrt(torch.clamp(var64, min=0.0))
                mean_t = mean64.to(device=device_obj, dtype=torch.float32)
                std_t = std64.to(device=device_obj, dtype=torch.float32)
            out[f"reward_{name}_mean"] = mean_t.detach()
            out[f"reward_{name}_std"] = std_t.detach()
        return out

    def _compose_exact_scm_reward(
        self,
        reward_raw,
        *,
        aux_reward=0.0,
        reward_clip=10.0,
        mode="none",
        rms_eps=1e-6,
        tanh_c=1.0,
        tanh_bound=2.0,
    ):
        reward_base = self._transform_exact_scm_base_reward(
            reward_raw,
            reward_clip=reward_clip,
            mode=mode,
            rms_eps=rms_eps,
            tanh_c=tanh_c,
            tanh_bound=tanh_bound,
        )
        aux_reward_t = torch.as_tensor(aux_reward, device=reward_base.device, dtype=reward_base.dtype)
        while aux_reward_t.ndim < reward_base.ndim:
            aux_reward_t = aux_reward_t.unsqueeze(0)
        return reward_base + aux_reward_t

    def _transform_reinforce_rewards(self, rewards):
        mode = self._resolve_reinforce_reward_transform(self.config)
        if mode == "none":
            return rewards, {
                "mode": "none",
                "rms_eps": 1e-6,
                "tanh_c": 1.0,
                "tanh_bound": float("inf"),
            }
        if mode == "rms":
            rms_eps = self._resolve_reinforce_reward_rms_eps(self.config)
            finite_mask = torch.isfinite(rewards)
            if bool(finite_mask.any().item()):
                finite_rewards = rewards[finite_mask]
                rms = torch.sqrt(finite_rewards.square().mean() + float(rms_eps))
                rewards_t = rewards / rms
            else:
                rewards_t = rewards
            return rewards_t, {
                "mode": "rms",
                "rms_eps": float(rms_eps),
                "tanh_c": 1.0,
                "tanh_bound": float("inf"),
            }
        if mode == "clip":
            bound = self._resolve_reinforce_reward_tanh_bound(self.config)
            rewards_t = torch.clamp(rewards, min=-float(bound), max=float(bound))
            return rewards_t, {
                "mode": "clip",
                "rms_eps": 1e-6,
                "tanh_c": 1.0,
                "tanh_bound": float(bound),
            }
        if mode == "tanh":
            c = self._resolve_reinforce_reward_tanh_c(self.config)
            bound = self._resolve_reinforce_reward_tanh_bound(self.config)
            rewards_t = float(bound) * torch.tanh(rewards / float(c))
            return rewards_t, {
                "mode": "tanh",
                "rms_eps": 1e-6,
                "tanh_c": float(c),
                "tanh_bound": float(bound),
            }
        raise ValueError(f"Unknown reinforce reward transform mode: {mode}")

    @staticmethod
    def _transform_reward_with_params(
        reward,
        *,
        mode,
        rms_eps,
        tanh_c,
        tanh_bound,
    ):
        mode = str(mode).strip().lower()
        if mode == "none":
            return reward
        if mode == "rms":
            eps_t = torch.as_tensor(rms_eps, device=reward.device, dtype=reward.dtype)
            finite_mask = torch.isfinite(reward)
            if bool(finite_mask.any().item()):
                finite_reward = reward[finite_mask]
                rms = torch.sqrt(finite_reward.square().mean() + eps_t)
                return reward / rms
            return reward
        if mode == "clip":
            b_t = torch.as_tensor(tanh_bound, device=reward.device, dtype=reward.dtype)
            while b_t.ndim < reward.ndim:
                b_t = b_t.unsqueeze(0)
            return torch.clamp(reward, min=-b_t, max=b_t)
        if mode == "tanh":
            c_t = torch.as_tensor(tanh_c, device=reward.device, dtype=reward.dtype)
            b_t = torch.as_tensor(tanh_bound, device=reward.device, dtype=reward.dtype)
            while c_t.ndim < reward.ndim:
                c_t = c_t.unsqueeze(0)
            while b_t.ndim < reward.ndim:
                b_t = b_t.unsqueeze(0)
            return b_t * torch.tanh(reward / c_t)
        raise ValueError(f"Unknown reinforce reward transform mode: {mode}")

    def _transform_rollout_reward(self, reward, *, mode=None, rms_eps=None, tanh_c=None, tanh_bound=None):
        mode_resolved = (
            self._resolve_reinforce_reward_transform(self.config)
            if mode is None
            else str(mode).strip().lower()
        )
        rms_eps_resolved = (
            self._resolve_reinforce_reward_rms_eps(self.config)
            if rms_eps is None
            else rms_eps
        )
        tanh_c_resolved = (
            self._resolve_reinforce_reward_tanh_c(self.config)
            if tanh_c is None
            else tanh_c
        )
        tanh_bound_resolved = (
            self._resolve_reinforce_reward_tanh_bound(self.config)
            if tanh_bound is None
            else tanh_bound
        )
        return self._transform_reward_with_params(
            reward,
            mode=mode_resolved,
            rms_eps=rms_eps_resolved,
            tanh_c=tanh_c_resolved,
            tanh_bound=tanh_bound_resolved,
        )

    @staticmethod
    def _fit_to_slot(x, slot_dim):
        d = int(x.shape[-1])
        slot_dim = int(slot_dim)
        if d == slot_dim:
            return x
        if d > slot_dim:
            return x[..., :slot_dim]
        pad_shape = list(x.shape)
        pad_shape[-1] = slot_dim - d
        pad = torch.zeros(pad_shape, device=x.device, dtype=x.dtype)
        return torch.cat([x, pad], dim=-1)

    @staticmethod
    def _pack_pfn_input(obs_slot_t, action_slot_t, reward_t, reward_mask_t):
        reward_vec = reward_t.reshape(1)
        mask_vec = reward_mask_t.reshape(1)
        # Two-head layout:
        #   head-1: [obs_slot, reward, reward_mask]
        #   head-2: [action_slot]
        return torch.cat([obs_slot_t, reward_vec, mask_vec, action_slot_t], dim=-1)

    @staticmethod
    def _sample_reward_dropout_ratio(h):
        if not bool(h.get("reward_dropout_enabled", True)):
            return 0.0
        if bool(h.get("reward_dropout_randomize", True)):
            lo = float(h.get("reward_dropout_ratio_min", 0.1))
            hi = float(h.get("reward_dropout_ratio_max", 1.0))
            lo, hi = min(lo, hi), max(lo, hi)
            return float(np.random.uniform(lo, hi))
        return float(h.get("reward_dropout_ratio", 0.0))

    @staticmethod
    def _coerce_bool(value):
        if torch.is_tensor(value):
            if value.dtype == torch.bool:
                return value
            if value.numel() == 1:
                return bool(value.item())
            return value != 0
        if isinstance(value, str):
            return value.strip().lower() not in {"0", "false", "no", "off", ""}
        return bool(value)

